// Fast, side-effect-free freshness check for the committed generated files.
//
// Why this exists: editing owner-login-app.js (or the Sales engines, or any page
// asset, or a state-machine fixture) shifts line numbers, ?v= hashes and rendered
// tables that are baked into generated docs. CI catches the resulting staleness,
// but only ~18 minutes into the browser shards (generated-determinism-ext20,
// write-path-inventory, modules-ext15, sales-inventory-ext20j, state-machine). This
// runs the SAME generator commands those specs check against, in a couple of
// seconds, so a contributor sees "stale" immediately after a source edit instead of
// in CI.
//
//   node tests/tools/check-generated.js          → PASS/STALE report; exit 1 if stale
//   node tests/tools/check-generated.js --write   → regenerate in place (same as
//                                                   running each generator by hand)
//
// It reuses the existing generators unchanged:
//   module-map.js --write | write-paths.js --md --json --inventory-md
//   refresh-asset-versions.js | sales-inventory.js --write
//   fixtures/state-machines.js --md
// In check mode it snapshots each output's bytes, runs the generators, compares,
// then restores the snapshot — so it writes nothing and leaves the working tree
// exactly as it was, including if a generator fails part-way through.
//
// Deliberately NOT covered (a different kind of freshness, not a fast node render):
//   tests/baselines/requests.json — the recorded database-request baseline. It is
//   regenerated from a full browser run, not a node generator:
//     UPDATE_BASELINES=1 npx playwright test --config tests/playwright.config.js request-baseline --project desktop
//   `npm run ci:local` (or CI's request-baseline spec) is what guards it.
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const ROOT = path.join(__dirname, '..', '..');

// The generators and the files each one owns. Keep this in step with the tools
// and with the freshness specs (generated-determinism-ext20, write-path-inventory,
// modules-ext15, sales-inventory-ext20j, state-machine).
const GENERATORS = [
  { cmd: ['tests/tools/module-map.js', '--write'],
    outputs: ['docs/ops/APPLICATION_MODULE_MAP_EXT15.md'] },
  { cmd: ['tests/tools/write-paths.js', '--md', '--json', '--inventory-md'],
    outputs: ['docs/ops/WRITE_PATH_MATRIX.md', 'docs/ops/WRITE_PATH_INVENTORY.md', 'docs/ops/MUTATION_WRITE_PATH_INVENTORY.json'] },
  { cmd: ['tests/tools/refresh-asset-versions.js'],
    outputs: ['owner-login.html', 'change-password.html', 'search.html', 'dashboard.html', 'index.html', 'manual-order-entry.html'] },
  { cmd: ['tests/tools/sales-inventory.js', '--write'],
    outputs: ['docs/ops/SALES_INVENTORY.md'] },
  { cmd: ['tests/fixtures/state-machines.js', '--md'],
    outputs: ['docs/ops/STATE_MACHINES.md'] },
];

const allOutputs = [...new Set(GENERATORS.flatMap(g => g.outputs))];
const write = process.argv.includes('--write');
const abs = p => path.join(ROOT, p);
const read = p => { try { return fs.readFileSync(abs(p)); } catch { return null; } };

// Snapshot before (skipped in --write mode, where we keep the regenerated bytes).
const before = write ? null : Object.fromEntries(allOutputs.map(p => [p, read(p)]));
// Restore every output to its snapshot, so check mode is side-effect-free even
// when a generator throws part-way through (no partial changes left behind).
const restore = () => {
  if (write) return;
  for (const p of allOutputs) {
    const was = before[p], now = read(p);
    if (was === null) { if (now !== null) try { fs.unlinkSync(abs(p)); } catch {} }
    else if (now === null || !was.equals(now)) fs.writeFileSync(abs(p), was);
  }
};

for (const g of GENERATORS) {
  try {
    // stdio 'pipe' so a generator's own stdout does not pollute this report;
    // a non-zero exit throws and is surfaced below (never swallowed).
    execFileSync(process.execPath, g.cmd, { cwd: ROOT, stdio: 'pipe' });
  } catch (e) {
    restore();
    console.error('generator failed (working tree restored):', g.cmd.join(' '), '\n',
      (e.stderr || e.stdout || e.message || '').toString());
    process.exit(2);
  }
}

if (write) {
  console.log('regenerated:', allOutputs.join(', '));
  process.exit(0);
}

// Compare, then restore the snapshot so nothing is left changed on disk.
const stale = allOutputs.filter(p => {
  const was = before[p], now = read(p);
  return !((was === null && now === null) || (was !== null && now !== null && was.equals(now)));
});
restore();

if (stale.length) {
  console.error('STALE generated files (regenerate with `node tests/tools/check-generated.js --write`):');
  stale.forEach(p => console.error('  - ' + p));
  console.error('\nThese are exactly what CI\'s generated-determinism-ext20 / write-path-inventory /');
  console.error('modules-ext15 / sales-inventory-ext20j / state-machine specs check. Working tree left unchanged.');
  process.exit(1);
}
console.log('generated files are fresh (' + allOutputs.length + ' checked):', allOutputs.join(', '));
